CREATE TABLE IF NOT EXISTS delay_records (id INTEGER PRIMARY KEY, line VARCHAR(20) NOT NULL, station VARCHAR(100) NOT NULL, direction VARCHAR(20) NOT NULL, delay_minutes INTEGER NOT NULL DEFAULT 0, severity VARCHAR(20) NOT NULL DEFAULT 'normal', source VARCHAR(120) NOT NULL, announcement TEXT, recorded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_delay_records_line_recorded ON delay_records(line, recorded_at);
CREATE TABLE IF NOT EXISTS line_statuses (id INTEGER PRIMARY KEY, line VARCHAR(20) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'normal', average_delay_minutes REAL NOT NULL DEFAULT 0, active_incidents INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS station_metrics (id INTEGER PRIMARY KEY, line VARCHAR(20) NOT NULL, station VARCHAR(100) NOT NULL, average_delay_minutes REAL NOT NULL DEFAULT 0, trains_observed INTEGER NOT NULL DEFAULT 0, reliability_percent REAL NOT NULL DEFAULT 100, measured_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
